// Nightly: a catalog line that has been SENT TO HERMES belongs in the Processed catalog
// (client, 2026-08-19). Main and Other are the working desks — what is still being chased,
// priced and approved. Processed is the finished record, and it is also the dedup shield
// the extraction workflow relies on. Leaving sent lines on the working desks means the
// client scrolls past finished work every day to find the four rows that need attention.
//
// The move is a MOVE, not a copy and not a rewrite: only `catalog` changes. Every other
// field — status, sent_at, hermes_id, prices, notes — is left exactly as it is, so the row
// in the Processed tab is the same row, with its whole history intact.
//
// WHAT COUNTS AS SENT: `sent_at` is set. That is the only signal the send workflow writes
// and the same one the app's "Hermes" badge reads, so the two can never disagree. Status is
// deliberately NOT part of the test — a line cannot be sent without being approved first,
// and re-deriving that here would only create a second, drifting definition.
//
// The FIRST run sweeps everything already sent, however long ago; every run after it has
// only the previous day's sends to move.

const rows = $input.all();
const move = [];
for (const r of rows) {
  const j = r.json || {};
  // Re-checked here rather than in the query: the Supabase node's filter list has `is` but
  // no `not.is`, so "sent_at is not null" cannot be expressed as a filter.
  const sent = j.sent_at !== null && j.sent_at !== undefined && String(j.sent_at).trim() !== '';
  if (!sent) continue;
  // Belt and braces against the query: never rewrite a row that is already Processed.
  if (String(j.catalog == null ? 'main' : j.catalog) === 'processed') continue;
  if (j.id === null || j.id === undefined) continue;
  move.push({ json: { id: j.id, catalog: 'processed' } });
}

console.log('scanned ' + rows.length + ' live line(s); moving ' + move.length + ' sent line(s) to Processed');
// Zero to move is the normal case on a quiet day: the node returns nothing and the update
// below simply does not run.
return move;
